import { useState, useEffect } from "react";
import api from "../api";
import socket from "../socket";
import PaymentPage from "./PaymentPage";

export default function UserDashboard() {
  const [services, setServices] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [selectedService, setSelectedService] = useState(null);
  const [location, setLocation] = useState("");
  const [showPayment, setShowPayment] = useState(false);
  const [currentBooking, setCurrentBooking] = useState(null);
  const [user, setUser] = useState(null);

  useEffect(() => {
    // Fetch user info from token
    const token = localStorage.getItem("token");
    if (token) {
      const decoded = JSON.parse(atob(token.split(".")[1]));
      setUser(decoded);
    }

    // Load services
    loadServices();
    
    // Load user's bookings
    loadBookings();

    // Listen for booking updates
    socket.on("booking-update", (data) => {
      loadBookings();
    });

    return () => {
      socket.off("booking-update");
    };
  }, []);

  const loadServices = async () => {
    try {
      const response = await api.get("/services");
      setServices(response.data);
    } catch (err) {
      console.error("Error loading services:", err);
    }
  };

  const loadBookings = async () => {
    try {
      const response = await api.get("/bookings/my-bookings");
      setBookings(response.data);
    } catch (err) {
      console.error("Error loading bookings:", err);
    }
  };

  const handleBooking = (service) => {
    setSelectedService(service);
    setShowPayment(true);
  };

  const handlePaymentSuccess = async () => {
    try {
      const bookingData = {
        userId: user?.id,
        serviceName: selectedService.name,
        location: location,
        status: "pending",
        paymentStatus: "paid"
      };
      
      const response = await api.post("/bookings/book", bookingData);
      if (response.data === "Booking Created") {
        alert("Booking created successfully!");
        setShowPayment(false);
        setSelectedService(null);
        setLocation("");
        loadBookings();
      }
    } catch (err) {
      console.error("Error creating booking:", err);
      alert("Failed to create booking");
    }
  };

  const cancelBooking = async (bookingId) => {
    try {
      await api.post(`/bookings/status/${bookingId}`, { status: "cancelled" });
      loadBookings();
    } catch (err) {
      console.error("Error cancelling booking:", err);
    }
  };

  return (
    <div style={{ padding: "20px" }}>
      <h1>User Dashboard</h1>
      <p>Welcome, User!</p>

      <div style={{ marginBottom: "30px" }}>
        <h2>Available Services</h2>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: "15px" }}>
          {services.map((service) => (
            <div key={service._id} style={{ border: "1px solid #ccc", padding: "15px", borderRadius: "5px" }}>
              <h3>{service.name}</h3>
              <p>Category: {service.category}</p>
              <p>Rating: {service.rating} ⭐</p>
              <button 
                onClick={() => handleBooking(service)}
                style={{ padding: "8px 16px", cursor: "pointer" }}
              >
                Book Now
              </button>
            </div>
          ))}
        </div>
      </div>

      {showPayment && (
        <div style={{ border: "1px solid #ccc", padding: "20px", marginBottom: "30px" }}>
          <h3>Booking: {selectedService?.name}</h3>
          <div style={{ marginBottom: "15px" }}>
            <label>Location:</label>
            <input
              type="text"
              value={location}
              onChange={(e) => setLocation(e.target.value)}
              placeholder="Enter your location"
              style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            />
          </div>
          <PaymentPage onSuccess={handlePaymentSuccess} />
        </div>
      )}

      <div>
        <h2>My Bookings</h2>
        {bookings.length === 0 ? (
          <p>No bookings yet.</p>
        ) : (
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr style={{ backgroundColor: "#f0f0f0" }}>
                <th style={{ padding: "10px", border: "1px solid #ccc" }}>Service</th>
                <th style={{ padding: "10px", border: "1px solid #ccc" }}>Location</th>
                <th style={{ padding: "10px", border: "1px solid #ccc" }}>Status</th>
                <th style={{ padding: "10px", border: "1px solid #ccc" }}>Payment</th>
                <th style={{ padding: "10px", border: "1px solid #ccc" }}>Action</th>
              </tr>
            </thead>
            <tbody>
              {bookings.map((booking) => (
                <tr key={booking._id}>
                  <td style={{ padding: "10px", border: "1px solid #ccc" }}>{booking.serviceName}</td>
                  <td style={{ padding: "10px", border: "1px solid #ccc" }}>{booking.location}</td>
                  <td style={{ padding: "10px", border: "1px solid #ccc" }}>
                    <span style={{ 
                      color: booking.status === "accepted" ? "green" : 
                             booking.status === "rejected" ? "red" : "orange" 
                    }}>
                      {booking.status}
                    </span>
                  </td>
                  <td style={{ padding: "10px", border: "1px solid #ccc" }}>{booking.paymentStatus}</td>
                  <td style={{ padding: "10px", border: "1px solid #ccc" }}>
                    {booking.status === "pending" && (
                      <button 
                        onClick={() => cancelBooking(booking._id)}
                        style={{ padding: "5px 10px", cursor: "pointer", backgroundColor: "#ff4444", color: "white", border: "none" }}
                      >
                        Cancel
                      </button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      <button 
        onClick={() => {
          localStorage.removeItem("token");
          window.location.href = "/";
        }}
        style={{ marginTop: "30px", padding: "10px 20px", cursor: "pointer" }}
      >
        Logout
      </button>
    </div>
  );
}
